function* fib() { let [a, b] = [0, 1]; for (;;) { yield a; [a, b] = [b, a + b]; } }
function* count() { yield 1; yield 2; yield 3; }
function main(): void {
  const out: number[] = [];
  for (const v of fib()) { if (v > 50) break; out.push(v); }
  console.log(out);
  let sum = 0;
  for (const v of count()) { if (v >= 2) sum += v * 2; }
  console.log(sum, [...count()].map((v) => v + 1));
}
